Here is the commit message:
kdb: address -Wformat-security warnings

When -Wformat-security is not disabled, using a string pointer
as a format causes a warning:

kernel/debug/kdb/kdb_io.c: In function 'kdb_read':
kernel/debug/kdb/kdb_io.c:365:36: error: format not a string literal and no format arguments [-Werror=format-security]
  365 |                         kdb_printf(kdb_prompt_str);
      |                                    ^~~~~~~~~~~~~~
kernel/debug/kdb/kdb_io.c: In function 'kdb_getstr':
kernel/debug/kdb/kdb_io.c:456:20: error: format not a string literal and no format arguments [-Werror=format-security]
  456 |         kdb_printf(kdb_prompt_str);
      |                    ^~~~~~~~~~~~~~

Use an explcit "%s" format instead.

Signed-off-by: Arnd Bergmann <arnd@arndb.de>
Fixes: 5d5314d6795f ("kdb: core for kgdb back end (1 of 2)")
Reviewed-by: Douglas Anderson <dianders@chromium.org>
Link: https://lore.kernel.org/r/20240528121154.3662553-1-arnd@kernel.org
Signed-off-by: Daniel Thompson <daniel.thompson@linaro.org>

Here is the root cause:
The bug is caused by using a string pointer (`kdb_prompt_str`) directly as an argument in the `kdb_printf` function without specifying a format string. This practice can lead to format string vulnerabilities, as the compiler warns that the argument is not a string literal and lacks format specifiers, which can be exploited if the string contains unexpected content.

Here is the patch:

 static char *kdb_read(char *buffer, size_t bufsize)
 {
 	char *cp = buffer;
 	char *bufend = buffer+bufsize-2;	/* Reserve space for newline
 						 * and null byte */
 	char *lastchar;
 	char *p_tmp;
 	char tmp;
 	static char tmpbuffer[CMD_BUFLEN];
 	int len = strlen(buffer);
 	int len_tmp;
 	int tab = 0;
 	int count;
 	int i;
 	int diag, dtab_count;
 	int key, ret;

 	diag = kdbgetintenv("DTABCOUNT", &dtab_count);
 	if (diag)
 		dtab_count = 30;

 	if (len > 0) {
 		cp += len;
 		if (*(buffer+len-1) == '\n')
 			cp--;
 	}

 	lastchar = cp;
 	*cp = '\0';
 	kdb_printf("%s", buffer);
 poll_again:
 	key = kdb_getchar();
 	if (key != 9)
 		tab = 0;
 	switch (key) {
 	case 8: /* backspace */
 		if (cp > buffer) {
 			memmove(cp-1, cp, lastchar - cp + 1);
 			lastchar--;
 			cp--;
 			kdb_printf("\b%s ", cp);
 			kdb_position_cursor(kdb_prompt_str, buffer, cp);
 		}
 		break;
 	case 10: /* linefeed */
 	case 13: /* carriage return */
 		*lastchar++ = '\n';
 		*lastchar++ = '\0';
 		if (!KDB_STATE(KGDB_TRANS)) {
 			KDB_STATE_SET(KGDB_TRANS);
 			kdb_printf("%s", buffer);
 		}
 		kdb_printf("\n");
 		return buffer;
 	case 4: /* Del */
 		if (cp < lastchar) {
 			memmove(cp, cp+1, lastchar - cp);
 			lastchar--;
 			kdb_printf("%s ", cp);
 			kdb_position_cursor(kdb_prompt_str, buffer, cp);
 		}
 		break;
 	case 1: /* Home */
 		if (cp > buffer) {
 			cp = buffer;
 			kdb_position_cursor(kdb_prompt_str, buffer, cp);
 		}
 		break;
 	case 5: /* End */
 		if (cp < lastchar) {
 			kdb_printf("%s", cp);
 			cp = lastchar;
 		}
 		break;
 	case 2: /* Left */
 		if (cp > buffer) {
 			kdb_printf("\b");
 			--cp;
 		}
 		break;
 	case 14: /* Down */
 	case 16: /* Up */
 		kdb_printf("\r%*c\r",
 			   (int)(strlen(kdb_prompt_str) + (lastchar - buffer)),
 			   ' ');
 		*lastchar = (char)key;
 		*(lastchar+1) = '\0';
 		return lastchar;
 	case 6: /* Right */
 		if (cp < lastchar) {
 			kdb_printf("%c", *cp);
 			++cp;
 		}
 		break;
 	case 9: /* Tab */
 		if (tab < 2)
 			++tab;

 		tmp = *cp;
 		*cp = '\0';
 		p_tmp = strrchr(buffer, ' ');
 		p_tmp = (p_tmp ? p_tmp + 1 : buffer);
 		strscpy(tmpbuffer, p_tmp, sizeof(tmpbuffer));
 		*cp = tmp;

 		len = strlen(tmpbuffer);
 		count = kallsyms_symbol_complete(tmpbuffer, sizeof(tmpbuffer));
 		if (tab == 2 && count > 0) {
 			kdb_printf("\n%d symbols are found.", count);
 			if (count > dtab_count) {
 				count = dtab_count;
 				kdb_printf(" But only first %d symbols will"
 					   " be printed.\nYou can change the"
 					   " environment variable DTABCOUNT.",
 					   count);
 			}
 			kdb_printf("\n");
 			for (i = 0; i < count; i++) {
 				ret = kallsyms_symbol_next(tmpbuffer, i, sizeof(tmpbuffer));
 				if (WARN_ON(!ret))
 					break;
 				if (ret != -E2BIG)
 					kdb_printf("%s ", tmpbuffer);
 				else
 					kdb_printf("%s... ", tmpbuffer);
 				tmpbuffer[len] = '\0';
 			}
 			if (i >= dtab_count)
 				kdb_printf("...");
 			kdb_printf("\n");
-			kdb_printf(kdb_prompt_str);
+			kdb_printf("%s",  kdb_prompt_str);
 			kdb_printf("%s", buffer);
 			if (cp != lastchar)
 				kdb_position_cursor(kdb_prompt_str, buffer, cp);
 		} else if (tab != 2 && count > 0) {
 			/* How many new characters do we want from tmpbuffer? */
 			len_tmp = strlen(tmpbuffer) - len;
 			if (lastchar + len_tmp >= bufend)
 				len_tmp = bufend - lastchar;

 			if (len_tmp) {
 				/* + 1 ensures the '\0' is memmove'd */
 				memmove(cp+len_tmp, cp, (lastchar-cp) + 1);
 				memcpy(cp, tmpbuffer+len, len_tmp);
 				kdb_printf("%s", cp);
 				cp += len_tmp;
 				lastchar += len_tmp;
 				if (cp != lastchar)
 					kdb_position_cursor(kdb_prompt_str,
 							    buffer, cp);
 			}
 		}
 		kdb_nextline = 1; /* reset output line number */
 		break;
 	default:
 		if (key >= 32 && lastchar < bufend) {
 			if (cp < lastchar) {
 				memmove(cp+1, cp, lastchar - cp + 1);
 				lastchar++;
 				*cp = key;
 				kdb_printf("%s", cp);
 				++cp;
 				kdb_position_cursor(kdb_prompt_str, buffer, cp);
 			} else {
 				*++lastchar = '\0';
 				*cp++ = key;
 				/* The kgdb transition check will hide
 				 * printed characters if we think that
 				 * kgdb is connecting, until the check
 				 * fails */
 				if (!KDB_STATE(KGDB_TRANS)) {
 					if (kgdb_transition_check(buffer))
 						return buffer;
 				} else {
 					kdb_printf("%c", key);
 				}
 			}
 			/* Special escape to kgdb */
 			if (lastchar - buffer >= 5 &&
 			    strcmp(lastchar - 5, "$?#3f") == 0) {
 				kdb_gdb_state_pass(lastchar - 5);
 				strcpy(buffer, "kgdb");
 				KDB_STATE_SET(DOING_KGDB);
 				return buffer;
 			}
 			if (lastchar - buffer >= 11 &&
 			    strcmp(lastchar - 11, "$qSupported") == 0) {
 				kdb_gdb_state_pass(lastchar - 11);
 				strcpy(buffer, "kgdb");
 				KDB_STATE_SET(DOING_KGDB);
 				return buffer;
 			}
 		}
 		break;
 	}
 	goto poll_again;
 }


 char *kdb_getstr(char *buffer, size_t bufsize, const char *prompt)
 {
 	if (prompt && kdb_prompt_str != prompt)
 		strscpy(kdb_prompt_str, prompt, CMD_BUFLEN);
-	kdb_printf(kdb_prompt_str);
+	kdb_printf("%s", kdb_prompt_str);
 	kdb_nextline = 1;	/* Prompt and input resets line number */
 	return kdb_read(buffer, bufsize);
 }



